# Code generated by Claude
"""
Arms held still while the base drives forward, stops, turns and stops (the arm-swing symptom).

    source .venv/bin/activate
    python experiments/arm_hold_drive_test.py [--lock-tilt]   # --lock-tilt adds a diagnostic third run

Reproduces combined_controller.py's start-up (spawn, 1.0 s warm-up with every non-wheel actuator at
target 0, capture the drooped arm pose as the hold target, 0.4 s re-settle) and its velocity drive
(cruise-control ramp of 0.02 per viewer frame at 60 Hz, 1.5 m/s and 2 rad/s at full, qvel overwritten
every physics step, no roll/pitch, z free). Then the key schedule:
   0.0- 3.0 s  forward key held
   3.0- 5.5 s  stop (space)
   5.5- 8.5 s  turn-left key held
   8.5-11.0 s  stop (space)
Run twice with the same protocol: OLD = torque motors on the arm and fingers with the Python PD every
physics step, no armature, no gravcomp (what the app did before src/arm_actuators.py), NEW = what the app
does now: the position actuators with armature and gravity compensation (src/arm_actuators.py).
Reported: how far the hands move (in the torso frame, from their pre-drive position) and how far
each arm joint strays from its hold target.
"""

import sys
from pathlib import Path

import mujoco
import numpy as np

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))

from src import robot_specs  # noqa: E402
from src.arm_actuators import add_arm_actuators  # noqa: E402
from src.controller import RobotController  # noqa: E402
from src.pedestal import add_pedestal_lift  # noqa: E402

SCENE = PROJECT_ROOT / "models" / "scenes" / "chemistry_lab_combined.xml"
SPAWN = [-1.0, 3.5, 0.22]
HZ = robot_specs.PHYSICS_HZ
DT = robot_specs.SIMULATION_TIMESTEP
STEPS_PER_FRAME = round(HZ / 60)
INCR, MAX_LIN, MAX_ANG = 0.02, 1.5, 2.0
SCHEDULE = [("forward", 0.0, 3.0), ("stop", 3.0, 5.5), ("turn", 5.5, 8.5), ("stop 2", 8.5, 11.0)]
np.set_printoptions(precision=3, suppress=True, linewidth=150)


class Drive:
    def __init__(self, new, lock_tilt=False):
        self.new, self.lock_tilt = new, lock_tilt
        spec = mujoco.MjSpec.from_file(str(SCENE))
        if new:                                            # position actuators, armature, gravcomp
            add_arm_actuators(spec)
        add_pedestal_lift(spec, robot_specs.PEDESTAL_SPECS)
        self.m = m = spec.compile()
        m.opt.timestep = DT
        self.d = mujoco.MjData(m)
        names = [m.actuator(a).name for a in range(m.nu)]
        self.wheels = [names.index("left_motor"), names.index("right_motor")]
        self.nonwheel = [a for a in range(m.nu) if a not in self.wheels]
        self.arm = {s: [names.index(f"{s}_joint{i}_ctrl") for i in range(1, 8)] for s in ("left", "right")}
        self.arm_all = self.arm["left"] + self.arm["right"]
        self.qadr = [m.jnt_qposadr[m.actuator_trnid[a, 0]] for a in self.arm_all]
        self.lim = np.array([max(abs(m.actuator_forcerange[a, 0]), abs(m.actuator_forcerange[a, 1])) for a in self.arm_all])
        self.base_dof = m.jnt_dofadr[[j for j in range(m.njnt) if m.jnt_type[j] == 0][0]]
        self.torso = m.body("openarm_body_link0").id
        self.tcp = {s: m.body(f"openarm_{s}_hand_tcp").id for s in ("left", "right")}
        self.ctrl = RobotController(m)
        self.hold = np.zeros(m.nu)
        self.hold[names.index(robot_specs.PEDESTAL_SPECS["actuator_name"])] = robot_specs.PEDESTAL_SPECS["target_height"]
        self.d.qpos[0:3] = SPAWN
        mujoco.mj_forward(m, self.d)

    def apply_ctrl(self):
        d = self.d
        d.ctrl[:] = 0.0
        if self.new:                                       # position actuators: ctrl = target
            d.ctrl[self.nonwheel] = self.hold[self.nonwheel]
        else:                                              # old: Python PD torque every physics step
            pd = self.ctrl.step(self.hold, {"joint_angles": d.qpos, "joint_velocities": d.qvel})
            d.ctrl[self.nonwheel] = pd[self.nonwheel]

    def startup(self):
        m, d = self.m, self.d
        for _ in range(round(1.0 * HZ)):
            self.apply_ctrl()
            mujoco.mj_step(m, d)
        z1 = float(d.qpos[2])
        ped =[a for a in self.nonwheel if m.actuator(a).name == robot_specs.PEDESTAL_SPECS["actuator_name"]][0]
        for a in self.nonwheel:
            if a != ped:
                self.hold[a] = d.qpos[m.jnt_qposadr[m.actuator_trnid[a, 0]]]
                d.qvel[m.jnt_dofadr[m.actuator_trnid[a, 0]]] = 0.0
        mujoco.mj_forward(m, d)
        for _ in range(round(0.4 * HZ)):
            self.apply_ctrl()
            mujoco.mj_step(m, d)
        return z1, float(d.qpos[2])

    def hands(self):
        d = self.d
        R = d.xmat[self.torso].reshape(3, 3)
        return {s: R.T @ (d.xpos[t] - d.xpos[self.torso]) for s, t in self.tcp.items()}

    def run(self):
        m, d = self.m, self.d
        z1, z2 = self.startup()
        ref = self.hands()
        hold_arm = self.hold[self.arm_all]
        lin = ang = 0.0
        n_frames = round(SCHEDULE[-1][2] * 60)
        res = {name: dict(hand=np.zeros(2), joint=np.zeros(14), force=0.0) for name, _, _ in SCHEDULE}
        end_hand = None
        for fr in range(n_frames):
            t = fr / 60.0
            phase = next(n for n, a, b in SCHEDULE if a <= t < b)
            if phase == "forward":
                lin += INCR
            elif phase == "turn":
                ang += INCR
            else:                                           # stop ramps both to zero
                lin = max(0.0, lin - INCR) if lin > 0 else min(0.0, lin + INCR)
                ang = max(0.0, ang - INCR) if ang > 0 else min(0.0, ang + INCR)
            lin, ang = float(np.clip(lin, -1, 1)), float(np.clip(ang, -1, 1))
            qw, qx, qy, qz = d.qpos[3:7]
            yaw = np.arctan2(2 * (qw * qz + qx * qy), 1 - 2 * (qy * qy + qz * qz))
            vx, vy, wz = lin * MAX_LIN * np.cos(yaw), lin * MAX_LIN * np.sin(yaw), ang * MAX_ANG
            if self.new:
                self.apply_ctrl()
            for _ in range(STEPS_PER_FRAME):
                if not self.new:
                    self.apply_ctrl()
                d.qvel[self.base_dof + 0], d.qvel[self.base_dof + 1] = vx, vy
                d.qvel[self.base_dof + 3] = d.qvel[self.base_dof + 4] = 0.0
                d.qvel[self.base_dof + 5] = wz
                mujoco.mj_step(m, d)
                if self.lock_tilt:                         # diagnostic: force the base upright (yaw only), keep z
                    yw = np.arctan2(2 * (d.qpos[3] * d.qpos[6] + d.qpos[4] * d.qpos[5]), 1 - 2 * (d.qpos[5] ** 2 + d.qpos[6] ** 2))
                    d.qpos[3:7] = [np.cos(yw / 2), 0.0, 0.0, np.sin(yw / 2)]
                    d.qvel[self.base_dof + 2] = 0.0
                h = self.hands()
                r = res[phase]
                r["hand"] = np.maximum(r["hand"], [1000 * np.linalg.norm(h[s] - ref[s]) for s in ("left", "right")])
                r["joint"] = np.maximum(r["joint"], np.abs(d.qpos[self.qadr] - hold_arm))
                r["force"] = max(r["force"], 100 * float((np.abs(d.actuator_force[self.arm_all]) / self.lim).max()))
        h = self.hands()
        end_hand = [1000 * np.linalg.norm(h[s] - ref[s]) for s in ("left", "right")]
        return z1, z2, res, end_hand, float(np.abs(d.qpos[self.qadr] - hold_arm).max())


def main():
    names = [f"{s[0].upper()}j{i}" for s in ("left", "right") for i in range(1, 8)]
    runs = [("OLD (torque motors + Python PD, no gravcomp)", False, False),
            ("NEW (position actuators, armature, gravcomp)", True, False)]
    if "--lock-tilt" in sys.argv:                          # opt-in diagnostic, not what the app does
        runs.append(("NEW + base forced upright, no tilt/z-bounce (diagnostic, not in the app)", True, True))
    print("Arms held at their drooped rest pose; hands measured in the torso frame.\n", flush=True)
    for label, new, lt in runs:
        print(f"... {label}", file=sys.stderr, flush=True)
        z1, z2, res, end_hand, end_joint = Drive(new, lt).run()
        print(f"{label}: base z after warm-up {z1:.4f} m, after re-settle {z2:.4f} m")
        print(f"   {'phase':9s} {'hand move max L / R (mm)':>26s} {'worst joint deviation (rad)':>34s} {'peak arm force (% of limit)':>28s}")
        for ph, r in res.items():
            j = int(r["joint"].argmax())
            print(f"   {ph:9s} {r['hand'][0]:12.1f} / {r['hand'][1]:<10.1f} {r['joint'].max():20.3f} ({names[j]}) {r['force']:22.0f}%")
        print(f"   at the end (11 s): hands {end_hand[0]:.1f} / {end_hand[1]:.1f} mm from where they started; "
              f"worst joint {end_joint:.3f} rad from its target\n", flush=True)
    base = PROJECT_ROOT / "data" / "arm_swing_diagnostics"
    try:
        import csv
        peaks = {r["joint"]: float(r["peak_deviation_rad"]) for r in csv.DictReader(open(base / "baseline_peak.csv"))}
        arms = {k: v for k, v in peaks.items() if "joint" in k and "finger" not in k}
        hd = np.genfromtxt(base / "handdisp_0p020.csv", delimiter=",", names=True)
        print("Earlier logged measurement (data/arm_swing_diagnostics, Sep 29; the script that made it was not kept, so the "
              "drive profile may differ):")
        print(f"   baseline_peak.csv: worst arm joint deviation {max(arms.values()):.2f} rad ({max(arms, key=arms.get)}), "
              f"median over the 14 arm joints {np.median(list(arms.values())):.2f} rad")
        print(f"   handdisp_0p020.csv (ramp 0.02/frame, the app's value): peak hand displacement "
              f"{hd['left_hand_disp'].max():.3f} m left, {hd['right_hand_disp'].max():.3f} m right")
    except Exception as e:                                     # noqa: BLE001
        print("could not read the earlier measurement:", e)


if __name__ == "__main__":
    main()
